import { ttsLocaleOf, type LanguageCode } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { platform } from '@/lib/platform/index.js';
import { useCanSpeak } from '@/lib/useCanSpeak.js';
import styles from './Card.module.css';

interface SpeakerProps {
  text: string;
  lang: LanguageCode;
  /** Which of the prototype's three sizes to draw. */
  variant?: 'front' | 'back' | 'reveal';
}

const CLASS = {
  front: styles.speakBig,
  back: styles.speak,
  reveal: styles.revealSpeak,
} as const;

const SIZE = { front: 20, back: 18, reveal: 18 } as const;

/** Speaks a piece of text. Absent when the device has no voice for the language. */
export function Speaker({ text, lang, variant = 'back' }: SpeakerProps): React.JSX.Element | null {
  const canSpeak = useCanSpeak(lang);
  if (!canSpeak || text.trim() === '') return null;
  return (
    <button
      type="button"
      className={cx(CLASS[variant])}
      aria-label={t('action.speak')}
      onClick={(event) => {
        event.stopPropagation();
        platform.tts.speak(text, ttsLocaleOf(lang));
      }}
    >
      <Icon name="speaker" size={SIZE[variant]} weight={1.9} />
    </button>
  );
}
